b:includable.script:
//
(function () {
  var roots = [].slice.call(document.querySelectorAll('.mor-widget'));
  roots.forEach(function (root) {
    if (root.dataset.morBound) return;   // Blogger may run this script twice.
    root.dataset.morBound = '1';

    // ===== EDIT ZONE — your code goes here =========================
    // `root` is this widget's container. Query inside it, not the whole
    // page, so multiple copies don't collide. Raw <, >, && are all fine
    // in here because everything sits inside the //<![CDATA[ block.
    var btn = root.querySelector('.mor-widget-btn');
    var out = root.querySelector('.mor-widget-count');
    var n = 0;
    btn.addEventListener('click', function () {
      n = n + 1;                 // e.g. plain `<` and `&&` are safe here
      out.textContent = String(n);
    });
    // ===============================================================
  });
})();
//
